-- Correct council_election_candidates.candidate_display for candidates loaded before 18 Oct 2026 (2024, 2025 and
-- 2026 results). The importer showed ballot-paper names without a comma ("BELL Adam Justin") surname first and kept
-- bracketed "known as" text; scripts/import-council-election-results.js now decides each ward's name form and gives
-- "Forenames Surname" (John's approval, 18 Oct 2026). The new names were worked out with that same rule from
-- candidate_published; list for review: Claude outputs/council-results-2023/display-name-corrections-loaded.tsv.
-- 5667 rows. Old rows kept in public.council_election_candidates_backup_20261018i.
-- Each row is updated only while it still holds its old display name and published name; the file rolls back
-- unless exactly 5667 rows change.
\set ON_ERROR_STOP on
BEGIN;

