DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM display_fix;
  IF n <> 5667 THEN RAISE EXCEPTION 'expected 5667 corrections, found %', n; END IF;
  SELECT count(*) INTO n FROM public.council_election_candidates c JOIN display_fix f ON f.id = c.id
    WHERE c.candidate_published = f.published AND c.candidate_display = f.old_display;
  IF n <> 5667 THEN RAISE EXCEPTION 'expected 5667 rows still holding the old name, found %', n; END IF;
END $$;

CREATE TABLE public.council_election_candidates_backup_20261018i AS
  SELECT c.*, now() AS saved_at FROM public.council_election_candidates c WHERE c.id IN (SELECT id FROM display_fix);
ALTER TABLE public.council_election_candidates_backup_20261018i ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.council_election_candidates_backup_20261018i FROM anon, authenticated;

UPDATE public.council_election_candidates c SET candidate_display = f.new_display
  FROM display_fix f
  WHERE c.id = f.id AND c.candidate_published = f.published AND c.candidate_display = f.old_display;

DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.council_election_candidates_backup_20261018i;
  IF n <> 5667 THEN RAISE EXCEPTION 'backup holds % rows, expected 5667', n; END IF;
  SELECT count(*) INTO n FROM public.council_election_candidates c JOIN display_fix f ON f.id = c.id WHERE c.candidate_display = f.new_display;
  IF n <> 5667 THEN RAISE EXCEPTION 'expected 5667 rows with the new name, found %', n; END IF;
END $$;

SELECT b.candidate_published, b.candidate_display AS before, c.candidate_display AS after
  FROM public.council_election_candidates_backup_20261018i b JOIN public.council_election_candidates c ON c.id = b.id
  ORDER BY b.id LIMIT 8;

COMMIT;
